import React, { useEffect, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Lock, Eye, EyeOff, Loader2, CheckCircle2 } from 'lucide-react';
import BrandMark from '../components/BrandMark';
import { authService } from '../services/authService';
import { useCommunityAuth } from '../contexts/CommunityAuthContext';

const NAVY = '#0B1F3A';

/**
 * ResetPasswordPage — consumes ?token=... generated by /password/forgot,
 * updates the password, auto-establishes a session, redirects home.
 */
const ResetPasswordPage = () => {
  const [params] = useSearchParams();
  const token = params.get('token') || '';
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [showPwd, setShowPwd] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);
  const navigate = useNavigate();
  const { refresh } = useCommunityAuth();

  useEffect(() => {
    if (!token) setError('Enlace de recuperación inválido o incompleto.');
  }, [token]);

  const submit = async (e) => {
    e.preventDefault();
    if (busy) return;
    setError('');
    if (password.length < 8) return setError('La contraseña debe tener al menos 8 caracteres.');
    if (password !== confirm) return setError('Las contraseñas no coinciden.');
    setBusy(true);
    try {
      await authService.resetPassword({ token, password });
      await refresh();
      setDone(true);
      setTimeout(() => navigate('/', { replace: true }), 1600);
    } catch (err) {
      setError(err.message || 'No se pudo restablecer la contraseña.');
    } finally { setBusy(false); }
  };

  return (
    <main data-testid="reset-password-page" style={{
      minHeight: '100vh',
      background: `
        radial-gradient(circle at 20% 20%, rgba(59,130,246,0.18) 0%, transparent 40%),
        radial-gradient(circle at 80% 80%, rgba(236,72,153,0.18) 0%, transparent 45%),
        linear-gradient(160deg, #0A0F1C 0%, #0B1F3A 100%)`,
      color: '#FFFFFF', display: 'flex', alignItems: 'center', justifyContent: 'center',
      padding: '2rem 1rem',
    }}>
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}
        style={{
          width: '100%', maxWidth: 440, padding: '2.25rem 2rem 2rem',
          background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)',
          borderRadius: 22, backdropFilter: 'blur(20px)',
          boxShadow: '0 40px 80px rgba(0,0,0,0.35)', position: 'relative',
        }}>
        <Link to="/join" data-testid="reset-back" style={{
          display: 'inline-flex', alignItems: 'center', gap: '0.35rem',
          fontSize: '0.72rem', color: 'rgba(255,255,255,0.55)',
          textDecoration: 'none', marginBottom: '1rem',
        }}>
          <ArrowLeft size={13} /> Volver a iniciar sesión
        </Link>

        <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '1.25rem' }}>
          <BrandMark size={44} variant="full" showTagline to={null} />
        </div>

        <h1 style={{
          fontFamily: '"Space Grotesk", sans-serif',
          fontSize: 'clamp(1.4rem, 3vw, 1.75rem)', fontWeight: 700,
          letterSpacing: '-0.02em', textAlign: 'center', margin: 0, marginBottom: '0.4rem',
        }}>Nueva contraseña</h1>
        <p style={{
          fontSize: '0.85rem', color: 'rgba(255,255,255,0.6)',
          textAlign: 'center', margin: 0, marginBottom: '1.4rem',
        }}>Elige una contraseña segura de al menos 8 caracteres.</p>

        {done ? (
          <div data-testid="reset-success" style={{
            display: 'flex', alignItems: 'center', gap: 10,
            padding: '0.9rem 1rem', borderRadius: 12,
            background: 'rgba(0,200,150,0.1)', border: '1px solid rgba(0,200,150,0.35)',
            color: '#00E4A6', fontSize: '0.9rem', fontWeight: 600,
          }}>
            <CheckCircle2 size={18} /> Contraseña actualizada. Entrando…
          </div>
        ) : (
          <form onSubmit={submit} style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}
            data-testid="reset-form">
            <PwdInput value={password} onChange={setPassword} placeholder="Nueva contraseña"
              show={showPwd} onToggle={() => setShowPwd((v) => !v)} testid="reset-input-password" />
            <PwdInput value={confirm} onChange={setConfirm} placeholder="Confirmar contraseña"
              show={showPwd} onToggle={() => setShowPwd((v) => !v)} testid="reset-input-confirm" />

            <button type="submit" disabled={busy || !token} data-testid="reset-submit"
              style={{
                width: '100%', padding: '0.85rem', borderRadius: 12, marginTop: 6,
                background: 'linear-gradient(135deg, #00C896, #06B6D4)',
                color: NAVY, fontSize: '0.9rem', fontWeight: 800,
                border: 'none', cursor: busy ? 'wait' : 'pointer',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 8,
                opacity: busy || !token ? 0.7 : 1,
              }}>
              {busy && <Loader2 size={14} className="pcone-spin" />}
              Restablecer contraseña
            </button>

            {error && (
              <div data-testid="reset-error" style={{
                marginTop: '0.5rem', padding: '0.65rem 0.85rem', borderRadius: 10,
                background: 'rgba(255,90,90,0.08)', border: '1px solid rgba(255,90,90,0.3)',
                fontSize: '0.78rem', color: '#FCA5A5',
              }}>{error}</div>
            )}
          </form>
        )}

        <style>{`.pcone-spin { animation: pcSpin 1s linear infinite; }
          @keyframes pcSpin { to { transform: rotate(360deg); } }`}</style>
      </motion.div>
    </main>
  );
};

const PwdInput = ({ value, onChange, placeholder, show, onToggle, testid }) => (
  <div style={{ position: 'relative' }}>
    <Lock size={14} style={{
      position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)',
      color: 'rgba(255,255,255,0.4)',
    }} />
    <input type={show ? 'text' : 'password'} value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder} required autoComplete="new-password"
      data-testid={testid}
      style={{
        width: '100%', height: 44, boxSizing: 'border-box',
        padding: '0 2.5rem', borderRadius: 12,
        background: 'rgba(255,255,255,0.06)',
        border: '1px solid rgba(255,255,255,0.12)',
        color: '#FFFFFF', fontSize: '0.88rem', outline: 'none',
      }} />
    <button type="button" onClick={onToggle}
      aria-label={show ? 'Ocultar' : 'Mostrar'}
      style={{
        position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
        background: 'transparent', border: 'none', color: 'rgba(255,255,255,0.55)',
        cursor: 'pointer', display: 'inline-flex', alignItems: 'center',
      }}>
      {show ? <EyeOff size={15} /> : <Eye size={15} />}
    </button>
  </div>
);

export default ResetPasswordPage;
